def fw(a):
 a=list(a);h=1
 while h<len(a):
  for k in range(0,len(a),2*h):
   for j in range(k,k+h):a[j],a[j+h]=a[j]+a[j+h],a[j]-a[j+h]
  h*=2
 return a
def spec(v):return [F(x*x,len(v)**2) for x in fw(v)]
def influence(v):return F(sum(v[s]!=v[s^(1<<j)] for s in range(len(v)) for j in range((len(v)-1).bit_length())),len(v))
